using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationResourceOperations
{
    private static bool Finite(double value)=>double.IsFinite(value);
    private static bool Unit(Vector2 value)=>value.IsFinite()&&value.X>=0&&value.X<=1&&value.Y>=0&&value.Y<=1;
    private static bool OneOf(string value,params string[] choices)=>System.Array.IndexOf(choices,value)>=0;
    public string[] validate(Resource document)
    {
        var errors=new List<string>();var ids=new HashSet<string>();var size=document.Get("canvas_size").AsVector2I();double duration=document.Get("duration").AsDouble();if(document.Get("version").AsInt32()!=1)errors.Add("Unsupported Transformation Image version.");if(size.X<1||size.Y<1||size.X>8192||size.Y>8192||(long)size.X*size.Y>16777216)errors.Add("Canvas must be 1–8192 pixels per side and at most 16 megapixels.");if(!Finite(duration)||duration<=0||duration>86400)errors.Add("Invalid animation duration.");
        foreach(var raw in document.Get("components").AsGodotArray())
        {
            var item=raw.As<Resource>();if(item==null){errors.Add("Missing component.");continue;}string id=item.Get("id").AsString();if(id.Length==0||!ids.Add(id))errors.Add("Missing or duplicate component ID.");var states=new HashSet<string>();var keys=new HashSet<string>();var times=new HashSet<double>();var definitions=item.Get("states").AsGodotArray();if(definitions.Count==0)errors.Add("A component needs at least one state.");var baseSize=item.Get("base_size").AsVector2();if(!baseSize.IsFinite()||baseSize.X<=0||baseSize.Y<=0)errors.Add("Invalid component base dimensions.");
            foreach(var stateRaw in definitions)
            {
                var state=stateRaw.As<Resource>();if(state==null){errors.Add("Missing state.");continue;}string stateId=state.Get("id").AsString();if(stateId.Length==0||!states.Add(stateId))errors.Add("Missing or duplicate state ID.");var art=state.Get("artwork").As<Resource>();var texture=art?.Get("texture").As<Texture2D>();if(art==null||texture==null){errors.Add("Missing state artwork.");continue;}if(art.Get("kind").AsString()!="basic"||texture.GetWidth()<1||texture.GetHeight()<1||texture.GetWidth()>8192||texture.GetHeight()>8192||(long)texture.GetWidth()*texture.GetHeight()>16777216)errors.Add("State artwork must be a valid raster drawing of at most 8192 pixels per side / 16 megapixels.");double opacity=art.Get("opacity").AsDouble();var pivot=state.Get("pivot").AsVector2();if(opacity<0||opacity>1||pivot.X<0||pivot.X>1||pivot.Y<0||pivot.Y>1)errors.Add("State opacity and pivot must be within 0–1.");if(art.Get("id").AsString()!=id||art.Get("parent_id").AsString().Length>0)errors.Add("Invalid component artwork identity.");var dimensions=art.Get("dimensions").AsVector2();if(!art.Get("position").AsVector2().IsFinite()||!dimensions.IsFinite()||dimensions.X<=0||dimensions.Y<=0||!Finite(art.Get("rotation").AsDouble())||!Finite(opacity)||!pivot.IsFinite())errors.Add("Invalid state transform.");var properties=art.Get("properties").AsGodotDictionary();foreach(string axis in new[]{"basis_x","basis_y"})if(properties.TryGetValue(axis,out var value)&&(value.VariantType!=Variant.Type.Vector2||!value.AsVector2().IsFinite()))errors.Add("Invalid state affine transform.");
            }
            if(!states.Contains(item.Get("default_state_id").AsString()))errors.Add("Missing default state.");foreach(var keyRaw in item.Get("keys").AsGodotArray())
            {
                var key=keyRaw.As<Resource>();if(key==null){errors.Add("Missing keyframe.");continue;}string keyId=key.Get("id").AsString();if(keyId.Length==0||!keys.Add(keyId))errors.Add("Missing or duplicate keyframe ID.");if(!states.Contains(key.Get("state_id").AsString()))errors.Add("Keyframe references a missing state.");double time=key.Get("time").AsDouble(),snapped=Mathf.Snapped(time,.000001);if(!Finite(time)||time<0||time>duration||!times.Add(snapped))errors.Add("Invalid or overlapping keyframe times.");var a=key.Get("points_a").AsVector2Array();var b=key.Get("points_b").AsVector2Array();var path=key.Get("reveal_path").AsVector2Array();if(!OneOf(key.Get("mode").AsString(),"Auto Morph","Shape Morph","Guided Morph","Grow / Reveal","Step","Crossfade","Smooth morph","Linear morph","Reveal")||a.Length!=b.Length||a.Length>24||path.Length>64)errors.Add("Invalid transition controls.");if(!OneOf(key.Get("alignment").AsString(),"Bounds","Local")||!OneOf(key.Get("appearance").AsString(),"Feature reveal","Aligned blend")||!OneOf(key.Get("quality").AsString(),"Fast","High")||!OneOf(key.Get("reveal_mode").AsString(),"Point","Path","Directional","Shape expansion"))errors.Add("Invalid morph settings.");double preservation=key.Get("preservation").AsDouble(),bias=key.Get("topology_bias").AsDouble();if(!Finite(preservation)||preservation<0||preservation>1||!Unit(key.Get("morph_origin").AsVector2())||!Finite(key.Get("direction").AsDouble())||!Finite(bias)||Math.Abs(bias)>.15)errors.Add("Invalid morph parameter.");double width=key.Get("reveal_width").AsDouble();if(!Finite(width)||width<=0||width>2)errors.Add("Invalid reveal width.");var curve=key.Get("curve").As<Curve>();if(curve!=null){if(curve.PointCount<2||curve.PointCount>1024)errors.Add("A timing curve needs 2–1024 points.");for(int index=0;index<curve.PointCount;index++){var point=curve.GetPointPosition(index);if(!point.IsFinite()||point.X<0||point.X>1||!Finite(curve.GetPointLeftTangent(index))||!Finite(curve.GetPointRightTangent(index)))errors.Add("Invalid timing curve data.");}}foreach(var group in new[]{a,b,path})foreach(var point in group)if(!Unit(point))errors.Add("Invalid morph/reveal point.");for(int index=0;index<a.Length;index++)for(int j=0;j<index;j++)if(a[index].DistanceSquaredTo(a[j])<.00000001f||(a.Length==b.Length&&b[index].DistanceSquaredTo(b[j])<.00000001f))errors.Add("Conflicting correction pair coordinates.");
            }
        }
        ValidateEvents(document,duration,errors);return errors.ToArray();
    }
    private void ValidateEvents(Resource document,double duration,List<string> errors)
    {
        var events=document.Get("component_events").AsGodotArray();var eventIds=new HashSet<string>();var births=new Dictionary<string,double>();var splitCounts=new Dictionary<string,int>();Variant Get(Settings entry,string key)=>entry.TryGetValue(key,out var value)?value:default;bool Number(Variant value)=>value.VariantType is Variant.Type.Float or Variant.Type.Int;
        foreach(var raw in events)
        {
            var entry=raw.AsGodotDictionary();var id=Get(entry,"id");if(id.VariantType!=Variant.Type.String||id.AsString().Length==0||!eventIds.Add(id.AsString())){errors.Add("Invalid component event ID.");continue;}string kind=Get(entry,"kind").AsString();var target=Get(entry,"target");if(!OneOf(kind,"Split","Merge")||target.VariantType!=Variant.Type.String||lookup(document,"components",target.AsString())==null||births.ContainsKey(target.AsString())){errors.Add("Invalid component event target.");continue;}var at=Get(entry,"time");if(!Number(at)||!Finite(at.AsDouble())||at.AsDouble()<0||at.AsDouble()>duration){errors.Add("Invalid component event time.");continue;}births[target.AsString()]=at.AsDouble();var sources=Get(entry,"sources");if(sources.VariantType!=Variant.Type.PackedStringArray||sources.AsStringArray().Length==0){errors.Add("Invalid component event sources.");continue;}var sourceArray=sources.AsStringArray();if(kind=="Merge"&&sourceArray.Length<2)errors.Add("A merge needs at least two source components.");var seen=new HashSet<string>();foreach(string source in sourceArray){if(source==target.AsString()||lookup(document,"components",source)==null)errors.Add("Missing component transfer source.");if(!seen.Add(source))errors.Add("Duplicate transfer source.");}if(kind=="Split"){var mask=Get(entry,"mask");if(sourceArray.Length!=1||mask.VariantType!=Variant.Type.Object||mask.AsGodotObject() is not Texture2D texture){errors.Add("Invalid split mask.");continue;}string source=sourceArray[0];int count=splitCounts.TryGetValue(source,out var previous)?previous+1:1;splitCounts[source]=count;if(count>4)errors.Add("At most four disjoint split masks per source.");if(texture.GetWidth()<1||texture.GetHeight()<1||texture.GetWidth()>8192||texture.GetHeight()>8192||(long)texture.GetWidth()*texture.GetHeight()>16777216)errors.Add("Split mask exceeds image limits.");}
        }
        var dependencies=new Dictionary<string,List<string>>();foreach(var raw in events){var entry=raw.AsGodotDictionary();var sources=Get(entry,"sources");var at=Get(entry,"time");if(sources.VariantType==Variant.Type.PackedStringArray&&Number(at))foreach(string source in sources.AsStringArray())if(births.TryGetValue(source,out var birth)&&birth>at.AsDouble())errors.Add("A component transfer cannot precede its source's birth.");var target=Get(entry,"target");if(target.VariantType==Variant.Type.String&&births.ContainsKey(target.AsString())&&sources.VariantType==Variant.Type.PackedStringArray){var list=new List<string>();foreach(string source in sources.AsStringArray())if(births.ContainsKey(source))list.Add(source);dependencies[target.AsString()]=list;}}
        var resolved=new HashSet<string>();for(int pass=0;pass<=births.Count;pass++){var ready=new List<string>();foreach(var pair in dependencies){bool all=true;foreach(string id in pair.Value)all&=resolved.Contains(id);if(all){ready.Add(pair.Key);resolved.Add(pair.Key);}}foreach(string id in ready)dependencies.Remove(id);if(ready.Count==0)break;}if(dependencies.Count>0)errors.Add("Cyclic component transfers are not valid.");
    }
}
